import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"BaseServiceProvider","description":"","frontmatter":{"sidebarPos":3,"sidebarTitle":"BaseServiceProvider"},"headers":[],"relativePath":"system-reference/backend/providers/base-service-provider.md","filePath":"system-reference/backend/providers/base-service-provider.md","lastUpdated":1778363927000}'),r={name:"system-reference/backend/providers/base-service-provider.md"},a=o('<h1 id="baseserviceprovider" tabindex="-1">BaseServiceProvider <a class="header-anchor" href="#baseserviceprovider" aria-label="Permalink to &quot;BaseServiceProvider&quot;">​</a></h1><p><strong>Class</strong>: <code>Unusualify\\Modularous\\Providers\\BaseServiceProvider</code><br><strong>Source</strong>: <code>src/Providers/BaseServiceProvider.php</code><br><strong>Extends</strong>: <a href="./service-provider"><code>ServiceProvider</code></a></p><p>The core provider that handles all container bindings, macro registration, view composers, log channels, and the application scheduler. It is the heaviest provider in the stack and is registered by <a href="./modularous-provider"><code>ModularousProvider</code></a>.</p><h2 id="register" tabindex="-1"><code>register()</code> <a class="header-anchor" href="#register" aria-label="Permalink to &quot;`register()`&quot;">​</a></h2><h3 id="helper-files" tabindex="-1">Helper files <a class="header-anchor" href="#helper-files" aria-label="Permalink to &quot;Helper files&quot;">​</a></h3><p>All PHP files in <code>src/Helpers/</code> are required in sequence so global helper functions are available globally.</p><h3 id="config-merging" tabindex="-1">Config merging <a class="header-anchor" href="#config-merging" aria-label="Permalink to &quot;Config merging&quot;">​</a></h3><table><thead><tr><th>Source</th><th>Merged into</th></tr></thead><tbody><tr><td><code>config/config.php</code></td><td><code>modularous.*</code></td></tr><tr><td><code>config/merges/*.php</code></td><td><code>modularous.{filename}.*</code></td></tr><tr><td><code>config/disks.php</code></td><td><code>filesystems.disks.*</code></td></tr></tbody></table><h3 id="container-bindings-singletons" tabindex="-1">Container bindings (singletons) <a class="header-anchor" href="#container-bindings-singletons" aria-label="Permalink to &quot;Container bindings (singletons)&quot;">​</a></h3><table><thead><tr><th>Binding key</th><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><code>RepositoryInterface</code></td><td><code>Modularous</code></td><td>Overrides nwidart&#39;s <code>LaravelFileRepository</code> with the Modularous-extended implementation</td></tr><tr><td><code>modularous</code></td><td>alias for <code>Modularous</code></td><td>Convenience alias</td></tr><tr><td><code>modularous.navigation</code></td><td><code>ModularousNavigation</code></td><td>Admin navigation service</td></tr><tr><td><code>model.relation.namespace</code></td><td>—</td><td>Eloquent relations namespace string</td></tr><tr><td><code>model.relation.pattern</code></td><td>—</td><td>Regex pattern derived from relation namespace</td></tr><tr><td><code>unusualify.hosting</code></td><td><code>HostRouting</code></td><td>Host-based routing helper</td></tr><tr><td><code>unusualify.hostRouting</code></td><td><code>HostRouteRegistrar</code></td><td>Host-based route registrar</td></tr><tr><td><code>Filepond</code></td><td><code>FilepondManager</code></td><td>Filepond upload manager</td></tr><tr><td><code>currency.exchange</code></td><td><code>CurrencyExchangeService</code></td><td>Currency exchange rates</td></tr><tr><td><code>CurrencyProviderInterface</code></td><td>Resolved at runtime</td><td>Uses <code>modularous.currency_provider</code> config; falls back to <code>SystemPricingCurrencyProvider</code> then <code>NullCurrencyProvider</code></td></tr><tr><td><code>modularous.relationship.graph</code></td><td><code>CacheRelationshipGraph</code></td><td>Relationship dependency graph for cache invalidation</td></tr><tr><td><code>modularous.cache</code></td><td><code>ModularousCacheService</code></td><td>Package-level cache service</td></tr><tr><td><code>migration.backup</code></td><td><code>MigrationBackup</code></td><td>Migration backup utility</td></tr><tr><td><code>modularous.redirect</code></td><td><code>RedirectService</code></td><td>Redirect management</td></tr><tr><td><code>modularous.utm</code></td><td><code>UtmParameters</code></td><td>UTM parameter tracking</td></tr><tr><td><code>auth.register</code></td><td><code>RegisterBrokerManager</code></td><td>Auth registration broker</td></tr><tr><td><code>inertia.middleware</code></td><td><code>HandleInertiaRequests</code></td><td>Inertia request handler</td></tr></tbody></table><h3 id="aliases" tabindex="-1">Aliases <a class="header-anchor" href="#aliases" aria-label="Permalink to &quot;Aliases&quot;">​</a></h3><table><thead><tr><th>Alias</th><th>Class</th></tr></thead><tbody><tr><td><code>ModularousVite</code></td><td><code>Facades\\ModularousVite</code></td></tr><tr><td><code>GeoIP</code></td><td><code>Torann\\GeoIP\\Facades\\GeoIP</code></td></tr></tbody></table><h3 id="translation-service" tabindex="-1">Translation service <a class="header-anchor" href="#translation-service" aria-label="Permalink to &quot;Translation service&quot;">​</a></h3><p>Extends Laravel&#39;s <code>translation.loader</code> with a multi-path <code>FileLoader</code> that searches:</p><ol><li><code>vendor/laravel/framework/.../Translation/lang</code></li><li>Package <code>lang/</code></li><li>Application <code>lang/</code> (when not overridden by <code>modularous/lang/</code>)</li><li><code>app[&#39;path.lang&#39;]</code></li></ol><p>Extends <code>translator</code> with a custom <code>Translator</code> instance that reads from these paths in order.</p><h2 id="boot" tabindex="-1"><code>boot()</code> <a class="header-anchor" href="#boot" aria-label="Permalink to &quot;`boot()`&quot;">​</a></h2><h3 id="auth-config-validation" tabindex="-1">Auth config validation <a class="header-anchor" href="#auth-config-validation" aria-label="Permalink to &quot;Auth config validation&quot;">​</a></h3><p>When <code>enabled.users-management</code> is on and not running in console, validates that the Modularous auth guard, provider, and password config all exist in <code>config/auth</code>. Throws <code>AuthConfigurationException</code> with a descriptive message if any are missing.</p><h3 id="media-and-file-service-singletons" tabindex="-1">Media and file service singletons <a class="header-anchor" href="#media-and-file-service-singletons" aria-label="Permalink to &quot;Media and file service singletons&quot;">​</a></h3><table><thead><tr><th>Condition</th><th>Binding</th></tr></thead><tbody><tr><td><code>enabled.media-library</code> = true</td><td><code>imageService</code> → class from <code>media_library.image_service</code> config</td></tr><tr><td><code>enabled.file-library</code> = true</td><td><code>fileService</code> → class from <code>file_library.file_service</code> config</td></tr></tbody></table><p>Local disk URL is auto-configured when endpoint type is <code>local</code> and disk matches the package default.</p><h3 id="macros" tabindex="-1">Macros <a class="header-anchor" href="#macros" aria-label="Permalink to &quot;Macros&quot;">​</a></h3><table><thead><tr><th>Macro</th><th>Target</th><th>Description</th></tr></thead><tbody><tr><td><code>Str::modularousSlug()</code></td><td><code>Illuminate\\Support\\Str</code></td><td>Slug with locale-aware dictionary from <code>slug-dictionary</code> translations</td></tr><tr><td><code>Collection::recursive()</code></td><td><code>Illuminate\\Support\\Collection</code></td><td>Recursively converts all nested arrays/objects to Collections</td></tr><tr><td><code>Request::getCachedUserCurrency()</code></td><td><code>Illuminate\\Support\\Facades\\Request</code></td><td>Returns user&#39;s currency from session or the default pricing currency</td></tr></tbody></table><h3 id="view-composers" tabindex="-1">View composers <a class="header-anchor" href="#view-composers" aria-label="Permalink to &quot;View composers&quot;">​</a></h3><p>Registered on <code>&#39;*&#39;</code> (all views) or specific layout views:</p><table><thead><tr><th>Composer</th><th>Views</th><th>Condition</th></tr></thead><tbody><tr><td>Inline</td><td><code>*</code></td><td>Always — injects <code>BASE_KEY</code>, <code>MODULAROUS_VIEW_NAMESPACE</code>, <code>SYSTEM_PACKAGE_VERSIONS</code></td></tr><tr><td><a href="./../http/view-composers/urls"><code>Urls</code></a></td><td><code>*</code></td><td>Always</td></tr><tr><td><a href="./../http/view-composers/current-user"><code>CurrentUser</code></a></td><td><code>admin.*</code>, <code>{baseKey}::*</code></td><td><code>enabled.users-management</code> = true</td></tr><tr><td><a href="./../http/view-composers/medias-uploader-config"><code>MediasUploaderConfig</code></a></td><td>master/app-inertia layouts</td><td><code>enabled.media-library</code> = true</td></tr><tr><td><a href="./../http/view-composers/files-uploader-config"><code>FilesUploaderConfig</code></a></td><td>master/app-inertia layouts</td><td><code>enabled.file-library</code> = true</td></tr><tr><td><a href="./../http/view-composers/localization"><code>Localization</code></a></td><td>master/auth/app-inertia layouts</td><td>Always</td></tr><tr><td>Inline render flags</td><td><code>admin.*</code>, <code>templates.*</code>, <code>{baseKey}::*</code></td><td>Always — injects <code>renderForBlocks</code>, <code>renderForModal</code></td></tr></tbody></table><h3 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h3><table><thead><tr><th>Command</th><th>Schedule</th></tr></thead><tbody><tr><td><code>modularous:fileponds:scheduler --days=7</code></td><td>Daily</td></tr><tr><td><code>telescope:prune --hours=168</code></td><td>Daily (appends to <code>logs/scheduler.log</code>)</td></tr><tr><td><code>modularous:scheduler:chatable</code></td><td>Every minute</td></tr></tbody></table><h3 id="log-channels" tabindex="-1">Log channels <a class="header-anchor" href="#log-channels" aria-label="Permalink to &quot;Log channels&quot;">​</a></h3><table><thead><tr><th>Channel</th><th>Driver</th><th>Description</th></tr></thead><tbody><tr><td><code>modularous</code></td><td><code>monolog</code> with <code>ModularousLogHandler</code></td><td>Package debug log; retention 14 days; level from <code>MODULAROUS_LOG_LEVEL</code> env</td></tr><tr><td><code>modularous-notification-failure</code></td><td><code>daily</code></td><td>Notification failure log; <code>storage/logs/modularous-notification-failure.log</code>; 14-day retention</td></tr></tbody></table><h3 id="password-reset-url" tabindex="-1">Password reset URL <a class="header-anchor" href="#password-reset-url" aria-label="Permalink to &quot;Password reset URL&quot;">​</a></h3><p>Overrides Laravel&#39;s default reset URL to point to <code>admin.password.reset</code> named route.</p><h3 id="php-artisan-about" tabindex="-1"><code>php artisan about</code> <a class="header-anchor" href="#php-artisan-about" aria-label="Permalink to &quot;`php artisan about`&quot;">​</a></h3><p>Adds a <strong>Modularous</strong> section to <code>php artisan about</code> output showing cache status, scan status, theme, URLs, vendor path, and version.</p>',35),c=[a];function i(s,n,l,h,u,p){return d(),t("div",null,c)}const b=e(r,[["render",i]]);export{m as __pageData,b as default};
